export function actualPrepFixture(options={}){const f=prepRecoveryFixture(options);f.input.operationId='actual-prep-fictional-operation';f.input.actualProductionDeclaration=ACTUAL_PREP_DECLARATION;return {...f,get actor(){return f.actor;},get cashier(){return f.cashier;},preview:(extra={})=>f.call('actual-preview',{...f.input,...extra}),async post(extra={}){const q=await f.call('actual-preview',f.input);if(q.status!==200)throw Error(JSON.stringify(q));return f.call('actual-commit',{operationId:f.input.operationId,actualProductionDeclaration:ACTUAL_PREP_DECLARATION,expectedFingerprint:q.body.expectedFingerprint,...(q.body.requiresWarningAcknowledgement?{warningAcknowledgement:{warningFingerprint:q.body.warningFingerprint,acknowledged:true}}:{}),...extra});},commitBody(q,extra={}){return {operationId:f.input.operationId,actualProductionDeclaration:ACTUAL_PREP_DECLARATION,expectedFingerprint:q.expectedFingerprint,...(q.requiresWarningAcknowledgement?{warningAcknowledgement:{warningFingerprint:q.warningFingerprint,acknowledged:true}}:{}),...extra};},async skipActual(){const out=await f.call('actual-preview',f.input);if(out.status===200&&out.body.reviewSaved)return out;if(out.status!==409||!out.body.review)throw Error(JSON.stringify(out));return f.call('actual-review-skip',{...f.input,branch:f.branch,declaredName:'Test Sauce',expectedIssueFingerprint:out.body.review.issueFingerprint,skipReason:'SkipForNow'});}};}
